/**
 * Privacy settings page — server component.
 *
 * Three cards: a GDPR-style data export, a per-category listing of the
 * caller's own facts with per-fact delete, and a read-only audit trail
 * of every mutation to their identity graph. Everything reads through
 * the framework's identity service (`@intelligo-dev/core/identity`) via
 * `actions/privacy.ts` — no direct database access here.
 */

import type { Metadata } from "next";
import { getFormatter, getTranslations } from "next-intl/server";

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { ExportDataButton } from "@/components/privacy/export-data-button";
import { FactList } from "@/components/privacy/fact-list";
import { getAuditTrail, listFacts } from "@/actions/privacy";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("privacy-settings");
  return { title: t("page.title") };
}

export default async function PrivacySettingsPage() {
  const t = await getTranslations("privacy-settings");
  const format = await getFormatter();
  const [facts, auditTrail] = await Promise.all([listFacts(), getAuditTrail()]);

  return (
    <div className="container mx-auto max-w-2xl space-y-6 px-4 py-8">
      <header>
        <h1 className="text-2xl font-semibold">{t("page.title")}</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          {t("page.description")}
        </p>
      </header>

      <Card>
        <CardHeader>
          <CardTitle>{t("page.export.title")}</CardTitle>
          <CardDescription>{t("page.export.description")}</CardDescription>
        </CardHeader>
        <CardContent>
          <ExportDataButton />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{t("page.yourData.title")}</CardTitle>
          <CardDescription>{t("page.yourData.description")}</CardDescription>
        </CardHeader>
        <CardContent>
          <FactList initialFacts={facts} />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{t("page.auditTrail.title")}</CardTitle>
          <CardDescription>
            {t("page.auditTrail.description", { count: auditTrail.length })}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {auditTrail.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              {t("page.auditTrail.empty")}
            </p>
          ) : (
            <ul className="divide-y divide-border">
              {auditTrail.map((row) => (
                <li key={row.id} className="py-3 text-sm">
                  <div className="flex items-center justify-between gap-4">
                    <span className="font-medium capitalize">
                      {row.action} · {row.targetKind}
                    </span>
                    <time
                      dateTime={new Date(row.createdAt).toISOString()}
                      className="shrink-0 text-xs text-muted-foreground"
                    >
                      {format.dateTime(new Date(row.createdAt), {
                        dateStyle: "medium",
                        timeStyle: "short",
                      })}
                    </time>
                  </div>
                  {row.reason && (
                    <p className="mt-1 text-xs text-muted-foreground">
                      {row.reason}
                    </p>
                  )}
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { Skeleton } from "@/components/ui/skeleton";

export default function PrivacyLoading() {
  return (
    <div className="container mx-auto max-w-2xl space-y-6 px-4 py-8">
      <div className="space-y-2">
        <Skeleton className="h-7 w-32" />
        <Skeleton className="h-4 w-80" />
      </div>

      <Skeleton className="h-36 rounded-lg" />
      <Skeleton className="h-64 rounded-lg" />
      <Skeleton className="h-56 rounded-lg" />
    </div>
  );
}

"use server";

/**
 * Privacy settings server actions — thin transport over the
 * framework's identity service (`@intelligo-dev/core/identity`):
 * authenticate the caller, call the service, map any
 * `IdentityServiceError` to a friendly message, and revalidate. No
 * business rules here — fact ownership checks, the memory-audit write,
 * and data-export aggregation all live in the service.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import {
  deleteFact as deleteFactService,
  exportIdentity as exportIdentityService,
  getAuditTrail as getAuditTrailService,
  isIdentityServiceError,
  listFacts as listFactsService,
  type IdentityExport,
  type UserFact,
  type UserMemoryAuditRow,
} from "@intelligo-dev/core/identity";

export type PrivacyActionResult<T = undefined> =
  | { success: true; data: T }
  | { success: false; error: string };

type Translator = Awaited<
  ReturnType<typeof getTranslations<"privacy-settings">>
>;

function friendlyMessage(t: Translator): Partial<Record<string, string>> {
  return {
    not_found: t("errors.notFound"),
    invalid_input: t("errors.invalidInput"),
    database_error: t("errors.databaseError"),
  };
}

function friendlyError(error: unknown, t: Translator): string {
  if (isIdentityServiceError(error)) {
    return friendlyMessage(t)[error.code] ?? error.message;
  }
  return error instanceof Error
    ? error.message
    : t("errors.somethingWentWrong");
}

const PRIVACY_SETTINGS_PATH = "/settings/privacy";
const AUDIT_TRAIL_PAGE_SIZE = 50;

/** The caller's own facts, most important and most confident first. */
export async function listFacts(): Promise<UserFact[]> {
  const { user, workspace } = await requireWorkspace();
  return listFactsService({ userId: user.id, workspaceId: workspace.id });
}

/** Delete one of the caller's own facts. Records the deletion in the audit trail. */
export async function deleteFact(factId: string): Promise<PrivacyActionResult> {
  const t = await getTranslations("privacy-settings");
  try {
    const { user, workspace } = await requireWorkspace();
    await deleteFactService(
      { userId: user.id, workspaceId: workspace.id },
      factId
    );
    revalidatePath(PRIVACY_SETTINGS_PATH);
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

/**
 * A GDPR-style export of everything stored about the caller: facts,
 * memories, their latest profile snapshot, and the full audit trail.
 * Client-triggered, in-browser download — not a streamed endpoint.
 */
export async function exportIdentity(): Promise<
  PrivacyActionResult<IdentityExport>
> {
  const t = await getTranslations("privacy-settings");
  try {
    const { user, workspace } = await requireWorkspace();
    const data = await exportIdentityService({
      userId: user.id,
      workspaceId: workspace.id,
    });
    return { success: true, data };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

/** The caller's most recent memory-audit rows, most recent first. */
export async function getAuditTrail(): Promise<UserMemoryAuditRow[]> {
  const { user, workspace } = await requireWorkspace();
  return getAuditTrailService(
    { userId: user.id, workspaceId: workspace.id },
    { limit: AUDIT_TRAIL_PAGE_SIZE }
  );
}

"use client";

/**
 * Triggers a GDPR-style export of everything the framework's identity
 * service knows about the current user. Calls the `exportIdentity`
 * server action directly and turns the JSON result into a browser
 * download — no dedicated API route needed for a one-off, per-user
 * dump this size.
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { Download } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { exportIdentity } from "@/actions/privacy";

export function ExportDataButton() {
  const t = useTranslations("privacy-settings");
  const [loading, setLoading] = useState(false);
  const [, startTransition] = useTransition();

  function handleExport() {
    setLoading(true);
    startTransition(async () => {
      try {
        const result = await exportIdentity();
        if (!result.success) {
          toast.error(result.error);
          return;
        }

        const blob = new Blob([JSON.stringify(result.data, null, 2)], {
          type: "application/json",
        });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `data-export-${new Date().toISOString().slice(0, 10)}.json`;
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(url);
        toast.success(t("exportButton.success"));
      } catch (error) {
        toast.error(t("exportButton.error"));
        console.error(error);
      } finally {
        setLoading(false);
      }
    });
  }

  return (
    <Button onClick={handleExport} disabled={loading}>
      <Download className="mr-2 h-4 w-4" />
      {loading ? t("exportButton.preparing") : t("exportButton.download")}
    </Button>
  );
}

"use client";

/**
 * Per-category listing of the caller's own facts, with per-fact
 * delete. Generalized from Acme's identity-graph-section.tsx.
 *
 * Copy is translated via `next-intl` (ADR-0010), but category labels
 * default to Title Case of the schema's category slug rather than a
 * message lookup: categories are open-ended, product-defined data (not
 * UI copy this item authors), so there is no fixed key set to
 * translate. A product that knows its own categories passes
 * `categoryLabels` — an already-localized slug → label map — and gets
 * proper names for the ones it recognizes, Title Case for the rest.
 *
 * Deletion is optimistic — the row disappears immediately — while the
 * `deleteFact` server action records the deletion in the audit trail
 * and revalidates the page server-side.
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { ChevronDown, ChevronRight, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { deleteFact } from "@/actions/privacy";
import type { UserFact } from "@intelligo-dev/core/db/schema";

function titleCase(value: string): string {
  return value.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

function groupByCategory(facts: UserFact[]): Map<string, UserFact[]> {
  const map = new Map<string, UserFact[]>();
  for (const fact of facts) {
    const list = map.get(fact.category) ?? [];
    list.push(fact);
    map.set(fact.category, list);
  }
  return map;
}

function readableValue(value: unknown): string {
  if (typeof value === "string") return value;
  if (value && typeof value === "object" && "label" in value) {
    return String((value as { label: unknown }).label);
  }
  return JSON.stringify(value);
}

export function FactList({
  initialFacts,
  categoryLabels,
}: {
  initialFacts: UserFact[];
  /** Localized labels for categories this product defines. */
  categoryLabels?: Record<string, string>;
}) {
  const t = useTranslations("privacy-settings");
  const [facts, setFacts] = useState(initialFacts);
  const [expanded, setExpanded] = useState<Set<string>>(
    () => new Set(groupByCategory(initialFacts).keys())
  );
  const [pending, startTransition] = useTransition();

  const grouped = groupByCategory(facts);

  function handleDelete(factId: string) {
    setFacts((current) => current.filter((fact) => fact.id !== factId));
    startTransition(async () => {
      await deleteFact(factId);
    });
  }

  function toggle(category: string) {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(category)) next.delete(category);
      else next.add(category);
      return next;
    });
  }

  if (facts.length === 0) {
    return (
      <div className="rounded-md border border-dashed px-6 py-10 text-center">
        <p className="text-sm font-medium">{t("factList.empty")}</p>
        <p className="mt-1 text-sm text-muted-foreground">
          {t("factList.emptyHint")}
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {Array.from(grouped.entries()).map(([category, items]) => {
        const isOpen = expanded.has(category);
        return (
          <div key={category} className="overflow-hidden rounded-lg border">
            <button
              type="button"
              onClick={() => toggle(category)}
              className="flex w-full items-center justify-between px-3 py-2 text-left transition-colors hover:bg-muted/50"
            >
              <span className="text-sm font-medium">
                {categoryLabels?.[category] ?? titleCase(category)}{" "}
                <span className="text-muted-foreground">({items.length})</span>
              </span>
              {isOpen ? (
                <ChevronDown className="h-4 w-4" />
              ) : (
                <ChevronRight className="h-4 w-4" />
              )}
            </button>
            {isOpen && (
              <ul className="divide-y divide-border">
                {items.map((fact) => (
                  <li
                    key={fact.id}
                    className="flex items-start justify-between gap-3 px-3 py-2"
                  >
                    <div className="min-w-0 flex-1">
                      <p className="text-sm">{readableValue(fact.value)}</p>
                      <p className="mt-0.5 text-xs text-muted-foreground">
                        {t("factList.metaLine", {
                          confidence: fact.confidence.toFixed(2),
                          importance: fact.importance,
                        })}
                      </p>
                    </div>
                    <Button
                      size="sm"
                      variant="ghost"
                      disabled={pending}
                      onClick={() => handleDelete(fact.id)}
                      className="h-7 w-7 shrink-0 p-0"
                      aria-label={t("factList.deleteAria")}
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        );
      })}
    </div>
  );
}

{
  "page": {
    "title": "Privacy",
    "description": "See, export, and delete what the AI has learned about you.",
    "export": {
      "title": "Export your data",
      "description": "Download everything stored about you — every fact, memory, profile snapshot, and audit record — as a single JSON file."
    },
    "yourData": {
      "title": "Your data",
      "description": "What the AI has learned about you, grouped by category. Deleting a fact removes it immediately."
    },
    "auditTrail": {
      "title": "Audit trail",
      "description": "The last {count} changes to your data, most recent first.",
      "empty": "No changes recorded yet."
    }
  },
  "exportButton": {
    "download": "Download my data",
    "preparing": "Preparing your download…",
    "success": "Your data was downloaded",
    "error": "Couldn't export your data. Please try again."
  },
  "factList": {
    "empty": "Nothing has been recorded about you yet.",
    "metaLine": "confidence {confidence} · importance {importance}",
    "deleteAria": "Delete this fact",
    "emptyHint": "As you chat, anything the assistant learns about you shows up here — and you can delete any of it."
  },
  "errors": {
    "notFound": "That item no longer exists, or isn't yours.",
    "invalidInput": "That request wasn't valid.",
    "databaseError": "Something went wrong. Please try again.",
    "somethingWentWrong": "Something went wrong."
  }
}

"use client";

/**
 * Error boundary for privacy settings. Renders the shared `RouteError` from the
 * `route-error` item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return <RouteError error={error} reset={reset} scope="settings-privacy" />;
}
